const ctx = $('Begin Render').first().json;
const trigger = $('When Executed by Another Workflow').first().json;
const response = $json ?? {};

const body =
  response.body && typeof response.body === 'object' && !Array.isArray(response.body)
    ? response.body
    : response;

let statusCode = Number(response.statusCode ?? response.status ?? 0);
if (!statusCode && body.status === 'ready') statusCode = 201;

const jobId = String(trigger.job_id ?? '').trim();
const runId = String(ctx.render_run_id ?? '').trim();
const expectedAudioSha = String(ctx.audio_sha256 ?? '').trim().toLowerCase();
const expectedDuration = Number(ctx.audio_duration_ms);
const expectedSceneCount = Number(ctx.expected_scene_count);
const expectedStorage = '/data/renders/' + jobId + '/final.mp4';
const expectedManifest = '/data/renders/' + jobId + '/manifest.json';

let expectedScenes = ctx.scenes_json;
if (typeof expectedScenes === 'string') {
  try { expectedScenes = JSON.parse(expectedScenes); } catch { expectedScenes = []; }
}
if (!Array.isArray(expectedScenes)) expectedScenes = [];

const expectedByScene = new Map();
for (const scene of expectedScenes) {
  const sceneId = String(scene?.scene_uuid ?? '').trim().toLowerCase();
  expectedByScene.set(sceneId, scene);
}

const segments = Array.isArray(body.segments) ? body.segments : [];
const seenScenes = new Set();
let segmentsValid =
  expectedScenes.length === expectedSceneCount &&
  segments.length === expectedSceneCount &&
  expectedSceneCount > 0;

let previousEnd = 0;
for (let i = 0; i < segments.length; i++) {
  const segment = segments[i] ?? {};
  const sceneId = String(segment.scene_uuid ?? '').trim().toLowerCase();
  const expected = expectedByScene.get(sceneId);

  const shotId = String(segment.shot_uuid ?? '').trim().toLowerCase();
  const assetId = String(segment.visual_asset_id ?? '').trim().toLowerCase();
  const assetSha = String(segment.asset_sha256 ?? '').trim().toLowerCase();
  const order = Number(segment.segment_order);
  const startMs = Number(segment.start_ms);
  const endMs = Number(segment.end_ms);
  const durationMs = Number(segment.duration_ms);

  if (
    !expected ||
    seenScenes.has(sceneId) ||
    order !== i + 1 ||
    shotId !== String(expected.shot_uuid ?? '').trim().toLowerCase() ||
    assetId !== String(expected.visual_asset_id ?? '').trim().toLowerCase() ||
    assetSha !== String(expected.asset_sha256 ?? '').trim().toLowerCase() ||
    startMs !== Number(expected.segment_start_ms) ||
    endMs !== Number(expected.segment_end_ms) ||
    durationMs !== endMs - startMs ||
    startMs !== previousEnd ||
    endMs <= startMs ||
    endMs > expectedDuration
  ) {
    segmentsValid = false;
    break;
  }

  seenScenes.add(sceneId);
  previousEnd = endMs;
}

if (
  seenScenes.size !== expectedSceneCount ||
  previousEnd !== expectedDuration
) {
  segmentsValid = false;
}

const gates = body.qa_gates && typeof body.qa_gates === 'object'
  ? body.qa_gates
  : {};
const gatesValid =
  gates.video_dimensions === true &&
  gates.video_codec === true &&
  gates.audio_codec === true &&
  gates.stream_counts === true &&
  gates.duration_match === true &&
  gates.scene_coverage === true &&
  gates.asset_hashes === true &&
  gates.source_audio_excluded === true;

const durationMs = Number(body.duration_ms);
const durationDelta = Number(body.duration_delta_ms);

const renderSuccess =
  statusCode === 201 &&
  body.status === 'ready' &&
  String(body.job_id ?? '').trim() === jobId &&
  String(body.storage_path ?? '').trim() === expectedStorage &&
  String(body.manifest_path ?? '').trim() === expectedManifest &&
  /^[0-9a-f]{64}$/.test(String(body.sha256 ?? '').trim().toLowerCase()) &&
  Number(body.bytes) > 0 &&
  Number(body.width) === 1080 &&
  Number(body.height) === 1920 &&
  String(body.video_codec ?? '').trim().toLowerCase() === 'h264' &&
  String(body.audio_codec ?? '').trim().toLowerCase() === 'aac' &&
  String(body.pix_fmt ?? '').trim().toLowerCase() === 'yuv420p' &&
  Number(body.fps_num) === 30 &&
  Number(body.fps_den) === 1 &&
  Number(body.video_stream_count) === 1 &&
  Number(body.audio_stream_count) === 1 &&
  Number(body.audio_duration_ms) === expectedDuration &&
  Number.isInteger(durationMs) &&
  durationMs > 0 &&
  Number.isInteger(durationDelta) &&
  durationDelta === Math.abs(durationMs - expectedDuration) &&
  durationDelta <= 100 &&
  String(body.input_audio_sha256 ?? '').trim().toLowerCase() === expectedAudioSha &&
  body.qa_passed === true &&
  gatesValid &&
  segmentsValid;

const providerMessage =
  body?.message ??
  body?.error ??
  response?.error?.message ??
  response?.message ??
  'render result failed validation';

return {
  json: {
    job_id: jobId,
    render_run_id: runId,
    render_success: renderSuccess,
    result: renderSuccess ? body : {},
    error_message: renderSuccess ? '' : String(providerMessage).slice(0, 3500),
  },
};

const ctx = $('Begin Render').first().json;
const source = $json ?? {};
const errorObject =
  source.error && typeof source.error === 'object' && !Array.isArray(source.error)
    ? source.error
    : {};

const message = [
  source.error_message,
  errorObject.message,
  source.message,
  source.description,
  typeof source.error === 'string' ? source.error : null,
].find((value) => typeof value === 'string' && value.trim().length > 0)
  ?? 'unspecified M9 render failure';

return {
  json: {
    render_run_id: String(ctx.render_run_id ?? '').trim(),
    error_message: ('M9 render/QA failed: ' + message.trim()).slice(0, 4000),
  },
};
